CREATE TABLE "Modifier" ("id" TEXT NOT NULL PRIMARY KEY, "internalKey" TEXT NOT NULL, "aura" TEXT NOT NULL, "displayText" TEXT NOT NULL, "statDescription" TEXT, "minRoll" REAL, "maxRoll" REAL, "weight" INTEGER, "category" TEXT NOT NULL DEFAULT 'Other', "notes" TEXT, "enabled" BOOLEAN NOT NULL DEFAULT true, "favorite" BOOLEAN NOT NULL DEFAULT false, "modifierDemandScore" REAL, "auraPopularityScore" REAL, "metaScore" REAL, "metaLastUpdated" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
